import { asId, type Id } from '@opensinnoh/core';

/** Contiguous value runs: `[start, [name at start, name at start+1, ...]]`. */
export type Runs = [number, string[]][];

/** Shape of `data/names.json` (generated by tools/names/generate.ts; names only). */
export interface NamesFile {
  source: string;
  /** Map header constant per zone id (`MAP_HEADER_TWINLEAF_TOWN`). */
  zones: string[];
  cameras: string[];
  /** `OVERWORLD_WEATHER_*` per field weather value (yearly values 32–36 included). */
  weathers: Runs;
  /** Field pocket constant per pocket value (`POCKET_MEDICINE`). */
  pockets: string[];
  species: (string | null)[];
  items: (string | null)[];
  trainers: (string | null)[];
  /** Trainer class constant per class id (`TRAINER_CLASS_RIVAL`). */
  trainerClasses: (string | null)[];
  /** `enum TrainerMessageType` (`TRMSG_PRE_BATTLE`). */
  trainerMessageTypes: Runs;
  /** pl_enc_data member names in NARC order (`encounters_route_201`). */
  encounters: string[];
  /** `enum TileBehavior` per behaviour byte (`TILE_BEHAVIOR_TALL_GRASS`). */
  tileBehaviors: (string | null)[];
  movementActions: Runs;
  objectGfx: Runs;
  flags: Runs;
  vars: Runs;
  /** Shared script id ranges: ids ≥ base run entry `id - base` of scr_seq member `file` with text bank `bank`. */
  scriptRanges: { base: number; file: number; bank: number }[];
  /** Per pl_msg bank: message ids (prefix + suffix), or null when the decomp generates the bank. */
  textBanks: { bank: string; prefix: string; messages: (string | null)[] | null }[];
  /** Per scr_seq member: file name and ScriptEntry names (prefix + suffix; null = unnamed or not unique). */
  scripts: { file: string; prefix: string; entries: (string | null)[] }[];
  /** Constant per value (`MOVE_POUND`, `ABILITY_STENCH`, `NATURE_HARDY`, `TYPE_FIRE`, …). */
  moves: (string | null)[];
  abilities: (string | null)[];
  natures: (string | null)[];
  types: (string | null)[];
  eggGroups: (string | null)[];
  expRates: (string | null)[];
  evolutionMethods: (string | null)[];
  moveClasses: (string | null)[];
  /** `enum MoveRange` in order: name 0 is the value 0, name i ≥ 1 the bit i − 1. */
  moveRanges: string[];
  /** `enum MoveFlag` in order: name i is bit i. */
  moveFlags: string[];
  battleEffects: (string | null)[];
  holdEffects: (string | null)[];
  /** `MART_SPECIALTIES_ID_*` per PokeMartSpecialties index. */
  martSpecialties: string[];
  /** Forms with their own pl_personal/wotbl member, in member order after the species. */
  dataForms: { species: string; form: number; name: string }[];
}

export interface CharmapFile {
  source: string;
  /** `[firstCode, chars]`: code firstCode+i is the i-th character of chars. */
  runs: [number, string][];
}

function fromRuns(runs: Runs): Map<number, string> {
  const m = new Map<number, string>();
  for (const [start, names] of runs) names.forEach((n, i) => m.set(start + i, n));
  return m;
}

/** Turns native indexes into pack IDs: decomp names where the table has them, else `platinum:<kind>/<index>`. */
export class Names {
  readonly flagNames: Map<number, string>;
  readonly varNames: Map<number, string>;
  readonly gfxNames: Map<number, string>;
  readonly movementNames: Map<number, string>;
  readonly trainerMessageNames: Map<number, string>;
  readonly weatherNames: Map<number, string>;

  constructor(
    readonly file: NamesFile,
    readonly ns = 'platinum',
  ) {
    this.flagNames = fromRuns(file.flags);
    this.varNames = fromRuns(file.vars);
    this.gfxNames = fromRuns(file.objectGfx);
    this.movementNames = fromRuns(file.movementActions);
    this.trainerMessageNames = fromRuns(file.trainerMessageTypes);
    this.weatherNames = fromRuns(file.weathers);
  }

  private id(name: string | null | undefined, kind: string, index: number | string): Id {
    return asId(`${this.ns}:${name ?? `${kind}/${index}`}`);
  }

  /** `platinum:OVERWORLD_WEATHER_FOG`, or `platinum:weather/<n>` for unnamed values. */
  weather(i: number): Id {
    return this.id(this.weatherNames.get(i), 'weather', i);
  }
  zone(i: number): Id {
    return this.id(this.file.zones[i], 'zone', i);
  }
  camera(i: number): Id {
    return this.id(this.file.cameras[i], 'camera', i);
  }
  flag(i: number): Id {
    return this.id(this.flagNames.get(i), 'flag', i);
  }
  var(i: number): Id {
    return this.id(this.varNames.get(i), 'var', i);
  }
  species(i: number): Id {
    return this.id(this.file.species[i], 'species', i);
  }
  item(i: number): Id {
    return this.id(this.file.items[i], 'item', i);
  }
  move(i: number): Id {
    return this.id(this.file.moves[i], 'move', i);
  }
  ability(i: number): Id {
    return this.id(this.file.abilities[i], 'ability', i);
  }
  nature(i: number): Id {
    return this.id(this.file.natures[i], 'nature', i);
  }
  type(i: number): Id {
    return this.id(this.file.types[i], 'type', i);
  }
  eggGroup(i: number): Id {
    return this.id(this.file.eggGroups[i], 'egg-group', i);
  }
  growthRate(i: number): Id {
    return this.id(this.file.expRates[i], 'growth-rate', i);
  }
  battleEffect(i: number): Id {
    return this.id(this.file.battleEffects[i], 'battle-effect', i);
  }
  trainer(i: number): Id {
    return this.id(this.file.trainers[i], 'trainer', i);
  }
  trainerClass(i: number): Id {
    return this.id(this.file.trainerClasses[i], 'trainer-class', i);
  }
  encounters(i: number): Id {
    return this.id(this.file.encounters[i], 'encounters', i);
  }
  tileBehavior(i: number): Id {
    return this.id(this.file.tileBehaviors[i], 'tile-behavior', i);
  }
  matrix(i: number): Id {
    return this.id(null, 'matrix', i);
  }
  chunk(i: number): Id {
    return this.id(null, 'chunk', i);
  }
  area(i: number): Id {
    return this.id(null, 'area', i);
  }
  light(i: number): Id {
    return this.id(null, 'light', i);
  }
  prop(i: number): Id {
    return this.id(null, 'prop', i);
  }

  /** Message `msg` of pl_msg bank `bank`. */
  text(bank: number, msg: number): Id {
    const b = this.file.textBanks[bank];
    const suffix = b?.messages?.[msg];
    return this.id(suffix == null ? null : (b as { prefix: string }).prefix + suffix, `text/${bank}`, msg);
  }

  scriptFileName(file: number): string {
    const f = this.file.scripts[file];
    if (!f) throw new Error(`names: no script file ${file}`);
    return f.file;
  }

  /** Entry `entry` of scr_seq member `file`: the ScriptEntry name, else `platinum:<FileName>/<entry>`. */
  scriptEntry(file: number, entry: number): Id {
    const f = this.file.scripts[file];
    if (!f) throw new Error(`names: no script file ${file}`);
    const suffix = f.entries[entry];
    return asId(`${this.ns}:${suffix == null ? `${f.file}/${entry}` : f.prefix + suffix}`);
  }

  /**
   * Script id (as stored in events and init scripts) → file and entry. 0 = none (the dummy script);
   * 1–1999 = the zone's own file, entry id-1; higher ids = the shared range whose base is the highest ≤ id.
   */
  scriptRef(scriptId: number, zoneScriptFile: number): { file: number; entry: number } | undefined {
    if (scriptId === 0) return undefined;
    let best: { base: number; file: number } | undefined;
    for (const r of this.file.scriptRanges) if (scriptId >= r.base && (!best || r.base > best.base)) best = r;
    return best ? { file: best.file, entry: scriptId - best.base } : { file: zoneScriptFile, entry: scriptId - 1 };
  }

  scriptLabel(scriptId: number, zoneScriptFile: number): Id | undefined {
    const ref = this.scriptRef(scriptId, zoneScriptFile);
    return ref && this.scriptEntry(ref.file, ref.entry);
  }
}

export function charTable(file: CharmapFile): Map<number, string> {
  const m = new Map<number, string>();
  for (const [start, chars] of file.runs) [...chars].forEach((c, i) => m.set(start + i, c));
  return m;
}
